import java.util.*;class ValidWordAbbr{Map<String,String>m=new HashMap<>();String a(String s){return s.length()<=2?s:""+s.charAt(0)+(s.length()-2)+s.charAt(s.length()-1);}public ValidWordAbbr(String[]d){for(String s:d){String k=a(s);if(!m.containsKey(k))m.put(k,s);else if(!m.get(k).equals(s))m.put(k,"#");}}public boolean isUnique(String w){String k=a(w);return !m.containsKey(k)||m.get(k).equals(w);}}
